const fs=require('fs'),assert=require('assert/strict'),{createClient}=require('@supabase/supabase-js');for(const l of fs.readFileSync('.env.local','utf8').split(/\r?\n/)){const m=l.match(/^([A-Z0-9_]+)=(.*)$/);if(m)process.env[m[1]]??=m[2].replace(/^['"]|['"]$/g,'');}const db=createClient(process.env.NEXT_PUBLIC_SUPABASE_URL,process.env.SUPABASE_SERVICE_ROLE_KEY,{auth:{persistSession:false}});(async()=>{const start=performance.now();const count=await db.from('products').select('id',{count:'exact',head:true}).eq('status','active').is('deleted_at',null);if(count.error)throw count.error;const pages=await Promise.all(Array.from({length:Math.ceil(count.count/1000)},(_,i)=>db.from('products').select('brand').eq('status','active').is('deleted_at',null).order('brand').range(i*1000,i*1000+999)));for(const p of pages)if(p.error)throw p.error;const rows=pages.flatMap(p=>p.data);const fullMs=Math.round(performance.now()-start);const rpcStart=performance.now(),rpc=await db.rpc('storefront_active_brand_names');if(rpc.error)throw rpc.error;const rpcMs=Math.round(performance.now()-rpcStart);assert.deepEqual([...new Set(rows.map(r=>r.brand).filter(v=>v?.trim()))].sort(),rpc.data.map(r=>r.brand).sort());const result={originalRows:rows.length,compactRows:rpc.data.length,originalRequests:1+pages.length,compactRequests:1,fullReadMs:fullMs,compactReadMs:rpcMs,originalJsonBytes:Buffer.byteLength(JSON.stringify(rows)),compactJsonBytes:Buffer.byteLength(JSON.stringify(rpc.data)),sameBrands:true};fs.mkdirSync('../../outputs/speed-round2-20261014',{recursive:true});fs.writeFileSync('../../outputs/speed-round2-20261014/brand-read-comparison.json',JSON.stringify(result,null,2));console.log(result);})().catch(e=>{console.error(e.message);process.exitCode=1});
